import{z as i,x as d,o as r,c as B,q as E,j as A,D as o,d as t,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"PCIe 事务与 BAR","description":"","frontmatter":{"title":"PCIe 事务与 BAR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pcie-tlp-bar.md","filePath":"cs/pcie-tlp-bar.md","lastUpdated":1791413859000}'),p={name:"cs/pcie-tlp-bar.md"};function P(C,a,m,D,M,c){const s=d("Mermaid");return r(),B("div",null,[a[2]||(a[2]=E('<h1 id="pcie-事务与-bar" tabindex="-1">PCIe 事务与 BAR <a class="header-anchor" href="#pcie-事务与-bar" aria-label="Permalink to &quot;PCIe 事务与 BAR&quot;">​</a></h1><div class="epigraph"><p>配置空间里的基址寄存器声明设备要把 MMIO 或预取内存窗口放在哪；CPU 的 load/store 变成 Memory TLP，完成包带回数据。</p><footer>—— 据 PCI-SIG PCI Express Base Specification；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/pcie-lanes">上一课</a>停在分层与 lane。<a href="/cs/bus-mmio">MMIO</a> 已说设备窗口。缺口是 <strong>TLP 与 BAR</strong>：哪些事务类型、完成（completion）如何对应一次 <code>lw</code>，配置软件如何给 BAR 分配物理地址。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TLP 类型：Memory Read/Write、IO（x86 遗留）、Configuration、Message（中断、错误）。非Posted 读需要完成 TLP；Posted 写可不等。BAR：设备在配置空间报告窗口大小与类型（32/64、预取），固件/OS 写入基址。缺口不是 lane 训练，而是<strong>地址译码</strong>：落在 BAR 的 PA 走向该端点，落在 DRAM 的走向内存控制器。</p><p>能力链表：MSI-X、电源、PCIe 能力，下一课中断用。</p><h3 id="bar-不是「dram-行地址」" tabindex="-1">BAR 不是「DRAM 行地址」 <a class="header-anchor" href="#bar-不是「dram-行地址」" aria-label="Permalink to &quot;BAR 不是「DRAM 行地址」&quot;">​</a></h3><p>窗口里的偏移由设备定义：门铃、队列基址、NVMe 控制器寄存器。写成 JEDEC 列命令没有意义。预取 BAR 允许桥投机读，MMIO 寄存器通常标非预取，以免副作用读。</p><p><span class="marginnote">PCI-SIG 规范描述配置空间与 TLP。Patterson/Hennessy 的 MMIO 在 PCIe 上具体化为本课。枚举在固件课还会露面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>枚举：DFS 扫描总线号/设备号/功能号，读 Vendor ID，分配 BAR。运行：CPU store → Memory Write TLP；load → Memory Read → Completion。DMA：设备当请求者发 TLP 访问主机内存（后课 DMA）。ACS 等隔离点名。</p>',11)),(r(),A(n,null,{default:o(()=>[l(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENUM%5B%22%E9%85%8D%E7%BD%AE%E6%9E%9A%E4%B8%BE%E5%86%99%20BAR%22%5D%20--%3E%20WIN%5B%22MMIO%20%E7%AA%97%E5%8F%A3%22%5D%0A%20%20CPU%5B%22CPU%20load%2Fstore%22%5D%20--%3E%20TLP%5B%22Memory%20TLP%22%5D%0A%20%20TLP%20--%3E%20EP%5B%22%E7%AB%AF%E7%82%B9%E8%AF%91%E7%A0%81%E5%81%8F%E7%A7%BB%22%5D%0A%20%20EP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%B8%AD%E6%96%AD%E7%94%A8%20Message%20%2F%20MSI%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与教学总线就绪信号对照：PCIe 用完成包与重试在数据链路层，CPU 看到的是更长的未缓存访问延迟。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"「Posted / 非 Posted」翻译成大白话：Posted 写像投进邮筒的信——塞进去就走，不等回执；非 Posted 读像挂号信——你必须等对方回一张「完成包」把数据捎回来，CPU 这条 load 才算有结果。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"MSI-X 表本身常在 BAR 里。NVMe 提交队列门铃是 BAR 里的寄存器写，触发设备去 DMA 描述符——后课散聚。本课钉事务与窗口。",-1)),(r(),A(n,null,{default:o(()=>[l(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22CPU%20%E5%8F%91%E5%87%BA%20load%20%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20R%5B%22%E6%A0%B9%E5%A4%8D%E5%90%88%E4%BD%93%E5%81%9A%E5%9C%B0%E5%9D%80%E8%AF%91%E7%A0%81%22%5D%0A%20%20R%20--%3E%7C%22%E8%AF%BB%E5%9C%B0%E5%9D%80%E8%90%BD%E5%9C%A8%20BAR%20%E7%AA%97%E5%8F%A3%E5%86%85%22%7C%20TLP%5B%22%E5%B0%81%E8%A3%85%E4%B8%BA%20Memory%20Read%20TLP%22%5D%0A%20%20TLP%20--%3E%20E%5B%22%E7%AB%AF%E7%82%B9%E8%AE%BE%E5%A4%87%E6%94%B6%E5%88%B0%E8%AF%B7%E6%B1%82%22%5D%0A%20%20E%20--%3E%20CMP%5B%22%E5%9B%9E%20Completion%20TLP%EF%BC%8C%E6%95%B0%E6%8D%AE%E9%9A%8F%E5%8C%85%E6%8D%8E%E5%9B%9E%22%5D%0A%20%20CMP%20--%3E%20C2%5B%22load%20%E5%AE%8C%E6%88%90%EF%BC%9A%E6%95%B0%E6%8D%AE%E5%A1%AB%E5%85%A5%20CPU%20%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p>这张图回答的问题是：一条 <code>lw</code> 怎么变成设备上的数据？CPU 只管发地址，根复合体做地址译码发现目标在某个 BAR 里，把请求包装成 Memory Read TLP 送下游；设备回 Completion，数据原路返回。对软件来说它还是一条普通的读指令，硬件把这些来回全部藏掉了。</p><p><span class="marginnote">数字实例：假设某设备 BAR 声明 4 KB 窗口、被分到基址 0xFEC00000，那么 CPU 访问 0xFEC00010 就是读这个设备寄存器偏移 16 字节处；同一个地址绝不会同时落到 DRAM——译码按窗口范围二选一。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 TLP 头字段，不把 SR-IOV VF BAR 展开成虚拟化课。不讨论对端 ATS。不进入 GPU BAR 的 resizable BAR 营销。</p><p><span class="marginnote">常见误区：以为设备寄存器和普通内存「一样快」。实际一次 MMIO 读要走 CPU → 根复合体 → 设备 → 完成包几个来回，比读 DRAM 慢一个量级以上；所以高性能驱动不会在热路径上反复读设备寄存器，能写不读、能批量不单个。</span></p><p>后课默认：设备寄存器经 BAR 成为 PA 窗口；访问是 Memory TLP，读有完成包。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BAR 由配置分配，定义 MMIO/预取窗口。</li><li>读非 Posted，写可 Posted；完成包带回 load 数据。</li><li>下一课中断从线变成写消息。</li><li>出处：PCI-SIG PCIe Base Spec；Patterson and Hennessy, COD。</li></ul>',8))])}const I=i(p,[["render",P]]);export{T as __pageData,I as default};
